import React, { useState, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { getUser } from '../../utils/auth';

const Sidebar = ({ onClose }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const user = getUser();
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [activeSection, setActiveSection] = useState('main');
  const [stats, setStats] = useState({
    totalBookings: 0,
    activeBookings: 0,
    pendingApprovals: 0,
    upcomingBookings: 0
  });

  const isActive = (path) => location.pathname === path;

  const handleLinkClick = () => {
    if (onClose) onClose();
  };

  // Simulate stats loading
  useEffect(() => {
    const loadStats = async () => {
      setTimeout(() => {
        setStats({
          totalBookings: Math.floor(Math.random() * 50) + 10,
          activeBookings: Math.floor(Math.random() * 10) + 2,
          pendingApprovals: Math.floor(Math.random() * 5),
          upcomingBookings: Math.floor(Math.random() * 8) + 1
        });
      }, 1000);
    };

    loadStats();
  }, []);

  const getMenuSections = () => {
    if (!user) return {};

    const baseSection = {
      main: [
        { 
          name: 'Dashboard', 
          path: '/user/dashboard', 
          icon: '🏠',
          iconActive: '🏡',
          description: 'Overview & Analytics',
          badge: null,
          color: 'blue'
        },
        { 
          name: 'Buat Booking', 
          path: '/user/booking', 
          icon: '➕',
          iconActive: '✨',
          description: 'Buat reservasi baru',
          badge: 'New',
          color: 'green'
        },
        { 
          name: 'Booking Saya', 
          path: '/user/mybookings', 
          icon: '📋',
          iconActive: '📊',
          description: 'Kelola booking Anda',
          badge: stats.activeBookings > 0 ? stats.activeBookings : null,
          color: 'orange'
        }
      ]
    };

    if (user.role === 'admin') {
      return {
        admin: [
          { 
            name: 'Admin Dashboard', 
            path: '/admin/dashboard', 
            icon: '👑',
            iconActive: '💎',
            description: 'System overview',
            badge: null,
            color: 'purple'
          },
          { 
            name: 'Kelola Booking', 
            path: '/admin/bookings', 
            icon: '📊',
            iconActive: '📈',
            description: 'Manage all bookings',
            badge: stats.pendingApprovals > 0 ? stats.pendingApprovals : null,
            color: 'blue'
          },
          { 
            name: 'Kelola Ruangan', 
            path: '/admin/rooms', 
            icon: '🏢',
            iconActive: '🏗️',
            description: 'Room management',
            badge: null,
            color: 'green'
          },
          { 
            name: 'Kelola Users', 
            path: '/admin/users', 
            icon: '👥',
            iconActive: '👨‍👩‍👧‍👦',
            description: 'User management',
            badge: null,
            color: 'indigo'
          },
          { 
            name: 'Zoom Settings', 
            path: '/admin/zoom', 
            icon: '💻',
            iconActive: '🖥️',
            description: 'Zoom configuration',
            badge: null,
            color: 'blue'
          }
        ],
        ...baseSection
      };
    }

    if (user.role === 'zoom_approver') {
      return {
        zoom: [
          { 
            name: 'Zoom Dashboard', 
            path: '/zoom/dashboard', 
            icon: '💻',
            iconActive: '🖥️',
            description: 'Zoom overview',
            badge: null,
            color: 'blue'
          },
          { 
            name: 'Zoom Requests', 
            path: '/zoom/requests', 
            icon: '📝',
            iconActive: '✅',
            description: 'Pending approvals',
            badge: stats.pendingApprovals > 0 ? stats.pendingApprovals : null,
            color: 'orange'
          }
        ],
        ...baseSection
      };
    }

    if (user.role === 'room_approver') {
      return {
        room: [
          { 
            name: 'Room Dashboard', 
            path: '/room/dashboard', 
            icon: '🏢',
            iconActive: '🏗️',
            description: 'Room overview',
            badge: null,
            color: 'green'
          },
          { 
            name: 'Room Requests', 
            path: '/room/requests', 
            icon: '📝',
            iconActive: '✅',
            description: 'Pending approvals',
            badge: stats.pendingApprovals > 0 ? stats.pendingApprovals : null,
            color: 'orange'
          },
          { 
            name: 'Kelola Ruangan', 
            path: '/logistik/rooms', 
            icon: '🏢',
            iconActive: '🏗️',
            description: 'Manage facilities',
            badge: null,
            color: 'green'
          }
        ],
        ...baseSection
      };
    }

    return baseSection;
  };

  const getRoleInfo = () => {
    const roleMap = {
      admin: { 
        label: 'Administrator', 
        icon: '👑',
        level: 'System Admin',
        headerBg: 'from-purple-600 via-purple-700 to-indigo-800',
        accentColor: 'purple'
      },
      zoom_approver: { 
        label: 'Zoom Approver', 
        icon: '💻',
        level: 'Zoom Manager',
        headerBg: 'from-blue-600 via-blue-700 to-cyan-800',
        accentColor: 'blue'
      },
      room_approver: { 
        label: 'Room Approver', 
        icon: '🏢',
        level: 'Facility Manager',
        headerBg: 'from-green-600 via-emerald-700 to-teal-800',
        accentColor: 'green'
      },
      user: { 
        label: 'User', 
        icon: '👤',
        level: 'Employee',
        headerBg: 'from-gray-600 via-slate-700 to-gray-800',
        accentColor: 'gray'
      }
    };
    return roleMap[user?.role] || roleMap.user;
  };

  const getDisplayName = () => {
    if (user?.name) return user.name;
    if (user?.email) return user.email.split('@')[0];
    return 'User';
  };

  const getBadgeColor = (color) => {
    const colorMap = {
      blue: 'bg-blue-500 text-white',
      green: 'bg-green-500 text-white',
      orange: 'bg-orange-500 text-white',
      purple: 'bg-purple-500 text-white',
      indigo: 'bg-indigo-500 text-white',
      red: 'bg-red-500 text-white',
      gray: 'bg-gray-500 text-white'
    };
    return colorMap[color] || 'bg-gray-500 text-white';
  };

  const getIconBgColor = (color, isActive = false) => {
    if (isActive) {
      const activeColorMap = {
        blue: 'bg-gradient-to-r from-blue-500 to-blue-600 text-white shadow-lg',
        green: 'bg-gradient-to-r from-green-500 to-green-600 text-white shadow-lg',
        orange: 'bg-gradient-to-r from-orange-500 to-orange-600 text-white shadow-lg',
        purple: 'bg-gradient-to-r from-purple-500 to-purple-600 text-white shadow-lg',
        indigo: 'bg-gradient-to-r from-indigo-500 to-indigo-600 text-white shadow-lg',
        red: 'bg-gradient-to-r from-red-500 to-red-600 text-white shadow-lg',
        gray: 'bg-gradient-to-r from-gray-500 to-gray-600 text-white shadow-lg'
      };
      return activeColorMap[color] || activeColorMap.gray;
    }
    
    const hoverColorMap = {
      blue: 'bg-blue-100 text-blue-600 group-hover:bg-blue-200',
      green: 'bg-green-100 text-green-600 group-hover:bg-green-200',
      orange: 'bg-orange-100 text-orange-600 group-hover:bg-orange-200',
      purple: 'bg-purple-100 text-purple-600 group-hover:bg-purple-200',
      indigo: 'bg-indigo-100 text-indigo-600 group-hover:bg-indigo-200',
      red: 'bg-red-100 text-red-600 group-hover:bg-red-200',
      gray: 'bg-gray-100 text-gray-600 group-hover:bg-gray-200'
    };
    return hoverColorMap[color] || hoverColorMap.gray;
  };

  const menuSections = getMenuSections();
  const roleInfo = getRoleInfo();

  return (
    // Sidebar tetap fixed
    <div className="sticky left-0 top-0 h-full w-72 bg-white shadow-xl border-r border-gray-200 flex flex-col z-40">
      
      {/* Header - Sticky */}
      <div className={`sticky top-0 z-20 bg-gradient-to-br ${roleInfo.headerBg}`}>
        <div className="relative p-4 text-white">
          <div className="flex items-center space-x-3 mb-3">
            <div className="relative">
              <div className="w-12 h-12 bg-white bg-opacity-20 rounded-xl flex items-center justify-center backdrop-blur-sm border border-white/30 shadow-lg">
                <span className="text-2xl">{roleInfo.icon}</span>
              </div>
              <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-400 rounded-full border-2 border-white"></div>
            </div>
            <div className="min-w-0 flex-1">
              <h2 className="text-base font-bold truncate">{getDisplayName()}</h2>
              <p className="text-xs opacity-90 truncate">{user?.email}</p>
            </div>
          </div>
          <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-white bg-opacity-20 text-white">
            <span className="mr-1">{roleInfo.icon}</span>
            {roleInfo.level}
          </span>
        </div>
      </div>

      {/* Stats - Sticky di bawah header */}
      <div className="sticky top-[110px] z-10 p-3 bg-gradient-to-br from-gray-50 via-blue-50 to-indigo-50 border-b border-gray-100">
        <div className="grid grid-cols-2 gap-2">
          <div className="bg-white p-3 rounded-xl shadow-md border border-gray-100">
            <div className="flex items-center space-x-2">
              <span className="text-blue-500">📊</span>
              <div>
                <div className="text-lg font-bold text-blue-600">{stats.totalBookings}</div>
                <div className="text-xs text-gray-500">Total</div>
              </div>
            </div>
          </div>
          <div className="bg-white p-3 rounded-xl shadow-md border border-gray-100">
            <div className="flex items-center space-x-2">
              <span className="text-green-500">✅</span>
              <div>
                <div className="text-lg font-bold text-green-600">{stats.activeBookings}</div>
                <div className="text-xs text-gray-500">Active</div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Menu scrollable */}
      <div className="flex-1 overflow-y-auto bg-gradient-to-b from-gray-50 to-white">
        <nav className="p-3 space-y-1">
          {Object.entries(menuSections).map(([sectionKey, items]) => (
            <div key={sectionKey} className="mb-4">
              <div className="text-xs font-bold text-gray-600 uppercase mb-2">{sectionKey}</div>
              {items.map((item) => (
                <Link
                  key={item.path}
                  to={item.path}
                  onClick={handleLinkClick}
                  className={`
                    group flex items-center space-x-3 p-3 rounded-xl transition-all duration-300
                    ${isActive(item.path)
                      ? 'bg-white shadow-md border-l-4 border-blue-500'
                      : 'text-gray-700 hover:bg-white hover:shadow-sm'
                    }
                  `}
                >
                  <div className={`w-10 h-10 flex items-center justify-center rounded-xl ${getIconBgColor(item.color, isActive(item.path))}`}>
                    {isActive(item.path) ? item.iconActive : item.icon}
                  </div>
                  <div className="flex-1">
                    <div className="font-semibold text-sm">{item.name}</div>
                    <div className="text-xs text-gray-500">{item.description}</div>
                  </div>
                </Link>
              ))}
            </div>
          ))}
        </nav>
      </div>

      {/* Footer - Sticky */}
      <div className="sticky bottom-0 z-20 p-3 border-t border-gray-200 bg-gray-50">
        <div className="text-center text-xs text-gray-500">
          © 2024 Bank BRI
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
